        url_for_err = append_get_query(url_for_err, data_pairs)
    try:
        status, hdrs, data, final_url = single_http_request(method, url_arg, flags, header_pairs, data_pairs, want_body=True)
    except Exception as e:
        log_fatal('bat.go:215', connection_error_message(method, url_for_err, e), 1)
