    if not vals: return 0.0
    vals = sorted(vals)
    idx = int(math.ceil((p/100.0)*len(vals))) - 1
    idx = max(0, min(idx, len(vals)-1))
    return vals[idx]

def run_bench(flags, rest):
    # Build once to validate args.
    method, url_arg, header_pairs, data_pairs = build_request(flags, rest)
    n = max(0, int(flags.get('N', 1000)))
    c = max(1, int(flags.get('C', 100)))
    results = []
    errors = {}
    lock = threading.Lock()
    counter = {'i': 0}
    start_all = time.time()
    def worker():
        while True:
            with lock:
                if counter['i'] >= n: return
                counter['i'] += 1
            st = time.time()
            try:
                status, hdrs, data, final_url = single_http_request(method, url_arg, flags, header_pairs, data_pairs, want_body=True)
                dt = time.time() - st
                with lock:
                    results.append((dt, status, len(data)))
            except Exception as e:
                dt = time.time() - st
                err = connection_error_message(method, ensure_url(url_arg), e).split(': ', 1)[-1]
                with lock:
                    errors[err] = errors.get(err, 0) + 1
    threads = [threading.Thread(target=worker) for _ in range(min(c, max(n,1)))]
    for t in threads: t.daemon = True; t.start()
    for t in threads: t.join()
    total = max(time.time() - start_all, 0.000001)
    if results:
        lats = [r[0] for r in results]
        total_data = sum(r[2] for r in results)
        avg = sum(lats)/len(lats)
        sys.stdout.write("\nSummary:\n")
        sys.stdout.write(f"  Total:\t{total:.4f} secs.\n")
        sys.stdout.write(f"  Slowest:\t{max(lats):.4f} secs.\n")
        sys.stdout.write(f"  Fastest:\t{min(lats):.4f} secs.\n")
        sys.stdout.write(f"  Average:\t{avg:.4f} secs.\n")
        sys.stdout.write(f"  Requests/sec:\t{(len(results)/total):.4f}\n")
        sys.stdout.write(f"  Total Data Received:\t{total_data} bytes.\n")
        per = int(total_data/len(results)) if results else 0
        sys.stdout.write(f"  Response Size per Request:\t{per} bytes.\n\n")
        counts = {}
        for _, st, _ in results: counts[st] = counts.get(st, 0)+1
        sys.stdout.write("Status code distribution:\n")
        for st in sorted(counts): sys.stdout.write(f"  [{st}]\t{counts[st]} responses\n")
        sys.stdout.write("\nResponse time histogram:\n")
        mn, mx = min(lats), max(lats)
        width = (mx-mn)/10.0 if mx > mn else 0.0
        maxbucket = 1
        buckets=[]
        for i in range(11):
            lo = mn + width*i
            if width == 0:
                cnt = len(lats) if i == 0 else 0
            elif i == 10:
                cnt = sum(1 for v in lats if v >= lo)
            else:
                hi = mn + width*(i+1)
                cnt = sum(1 for v in lats if lo <= v < hi)
            buckets.append((lo,cnt)); maxbucket=max(maxbucket,cnt)
        for lo,cnt in buckets:
            bar = '∎' * int(40*cnt/maxbucket) if cnt else ''
            sys.stdout.write(f"  {lo:.3f} [{cnt}]\t|{bar}\n")
        sys.stdout.write("\nLatency distribution:\n")
        for p in (10,25,50,75,90,95,99):
            if len(lats) >= 2 or p in (10,25):
                sys.stdout.write(f"  {p}% in {percentile(lats,p):.4f} secs.\n")
    if errors:
        sys.stdout.write("\nError distribution:\n")
        for msg, cnt in errors.items():
            sys.stdout.write(f"  [{cnt}]\t{msg}\n")
    sys.stdout.flush()
    return 0

def main(argv):
    try:
        flags, rest = parse_flags(argv)
    except FlagError as e:
        sys.stderr.write(str(e) + "\n")
        print_usage()
        return 2
    if flags.get('version'):
        sys.stdout.write(f"Version: {VERSION}\n")
        return 0
    if flags.get('bench'):
        return run_bench(flags, rest)
    do_request(flags, rest, suppress_output=False)
    return 0

if __name__ == '__main__':
    try:
        raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError:
        raise SystemExit(1)
