        name_part = stripped.split('=', 1)[0]
        val_present = '=' in stripped
        val = stripped.split('=', 1)[1] if val_present else None
        if name_part in ('h', 'help'):
            print_usage(); raise SystemExit(2)
        if name_part in known_string:
            if not val_present:
                if i + 1 >= len(argv):
                    raise FlagError(f"flag needs an argument: -{name_part}")
                i += 1; val = argv[i]
            flags[known_string[name_part]] = val
        elif name_part in known_int:
            if not val_present:
                if i + 1 >= len(argv):
                    raise FlagError(f"flag needs an argument: -{name_part}")
                i += 1; val = argv[i]
            try:
                flags[known_int[name_part]] = int(val, 10)
            except Exception:
                raise FlagError(f"invalid value \"{val}\" for flag -{name_part}: parse error")
        elif name_part in known_bool:
            if val_present:
                try:
                    b = parse_bool(val)
                except Exception:
                    raise FlagError(f"invalid boolean value \"{val}\" for -{name_part}: parse error")
            else:
                b = True
            flags[known_bool[name_part]] = b
        else:
            raise FlagError(f"flag provided but not defined: {normalize_flag_token(a)}")
        i += 1
    return flags, rest

def canonical_header_key(k):
    # Approximation of Go's textproto.CanonicalMIMEHeaderKey.
    parts = k.split('-')
    out = []
    for p in parts:
        if p == '':
            out.append(p)
        else:
            out.append(p[:1].upper() + p[1:].lower())
    return '-'.join(out)

def classify_items(items):
    headers = []
    data = []
    for it in items:
        if ':' in it:
            k, v = it.split(':', 1)
            headers.append((canonical_header_key(k), v))
        elif '=' in it:
            k, v = it.split('=', 1)
            if v.startswith('@'):
                path = v[1:]
                try:
                    with open(path, 'rb') as f:
                        raw = f.read()
                    try:
                        v = raw.decode('utf-8')
                    except UnicodeDecodeError:
                        v = raw.decode('latin1')
                except Exception:
                    v = ''
            data.append((k, v))
        else:
            # The original silently ignores unclassified items.
            pass
    return headers, data

def go_json_escape(s):
    return s.replace('&', '\\u0026').replace('<', '\\u003c').replace('>', '\\u003e').replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')

def make_json_body(data_pairs):
    mp = {}
    for k, v in data_pairs:
        mp[k] = v
    raw = json.dumps(mp, sort_keys=True, ensure_ascii=False, separators=(',', ':'))
    raw = go_json_escape(raw)
    return (raw + "\n").encode('utf-8')

def make_form_body(data_pairs):
    # Go map iteration made this unstable; keeping user order is the most useful deterministic behavior.
    return urlencode(data_pairs).encode('utf-8')

def encode_query_pairs(data_pairs):
    # Last duplicate wins, while retaining the position of its first occurrence (close enough for map-backed behavior).
    seen = {}
    order = []
    for k, v in data_pairs:
        if k not in seen:
            order.append(k)
        seen[k] = v
    return urlencode([(k, seen[k]) for k in order])

def ensure_url(url):
    if '://' not in url:
        url = 'http://' + url
    return url

def display_url_for_error(method, url):
    # A small normalization to match Go's URL String for the no-host http:// case.
    if url in ('http://', 'https://'):
        return url[:-2]
    return url

def build_request(flags, rest):
    if not rest:
        print_usage(); raise SystemExit(2)
    method = None
    idx = 0
    if rest[0].upper() in METHODS:
        method = rest[0].upper(); idx = 1
    if idx >= len(rest):
        log_fatal('filter.go:35', 'Miss the URL', 1)
    url_arg = rest[idx]
    items = rest[idx+1:]
    headers_list, data_pairs = classify_items(items)
    if method is None:
        method = 'POST' if (data_pairs or flags.get('body')) else 'GET'
    return method, url_arg, headers_list, data_pairs

def append_get_query(url, data_pairs):
    if not data_pairs:
        return url
    q = encode_query_pairs(data_pairs)
    if not q:
        return url
    p = urlparse(url)
    newq = (p.query + '&' + q) if p.query else q
    return urlunparse((p.scheme, p.netloc, p.path, p.params, newq, p.fragment))

def prepare_body_and_headers(method, flags, header_pairs, data_pairs):
    body = None
    # Explicit POST-like methods send an empty body with Content-Length: 0 even when there is no data.
    body_allowed = method not in ('GET', 'HEAD')
    if body_allowed:
        if flags.get('form'):
            body = make_form_body(data_pairs) if data_pairs else b''
        elif data_pairs:
            body = make_json_body(data_pairs)
        elif flags.get('body') != '':
            body = flags.get('body', '').encode('utf-8')
        else:
            body = b'' if method in ('POST', 'PUT', 'PATCH', 'DELETE') else None
        if flags.get('body') != '' and body is not None:
            # Raw body overrides encoded data, but the content-type chosen due to data remains.
            body = flags.get('body', '').encode('utf-8')
    headers = {}
    headers['Accept'] = 'application/json'
    headers['Accept-Encoding'] = 'gzip, deflate'
    headers['User-Agent'] = USER_AGENT
    for k, v in header_pairs:
        headers[canonical_header_key(k)] = v
    if flags.get('auth'):
        userpass = flags['auth']
        if ':' not in userpass:
            userpass = userpass + ':'
        token = base64.b64encode(userpass.encode('utf-8')).decode('ascii')
        headers['Authorization'] = 'Basic ' + token
    # Content type is set after user headers by the original helper, so it overwrites Content-Type.
    if body_allowed and data_pairs:
        if flags.get('form'):
            headers['Content-Type'] = 'application/x-www-form-urlencoded'
        else:
            headers['Content-Type'] = 'application/json'
    return body, headers

def go_like_json_error(data):
    if data == b'':
        return 'unexpected end of JSON input'
    s = data.decode('utf-8', 'replace')
    st = s.lstrip()
    if st.startswith('{') and len(st) > 1:
        # Common object-key failure: {bad
        c = st[1]
        if c not in ('"', '}'):
            return f"invalid character '{c}' looking for beginning of object key string"
    if st:
        c = st[0]
        return f"invalid character '{c}' looking for beginning of value"
    return 'unexpected end of JSON input'

def render_response(data, headers, pretty):
    sys.stdout.write('\n')
    ctype = ''
    for k, v in headers:
        if k.lower() == 'content-type':
            ctype = v
            break
    if pretty and 'application/json' in ctype.lower():
        try:
            # Preserve object order as present in the response bytes.
            text = data.decode('utf-8')
            obj = json.loads(text)
            out = json.dumps(obj, indent=2, ensure_ascii=False)
            sys.stdout.write(out)
        except Exception:
            sys.stdout.flush()
            log_fatal('http.go:122', 'Response Json Indent: ' + go_like_json_error(data), 1)
    else:
        try:
            sys.stdout.write(data.decode('utf-8'))
        except UnicodeDecodeError:
            sys.stdout.buffer.write(data)
    sys.stdout.flush()

def connection_error_message(method, url, exc):
    disp = display_url_for_error(method, url)
    mtitle = method.title() if method else 'Get'
    # Produce Go-ish messages for the common failures.
    if isinstance(exc, HTTPErrorForLog):
        reason = exc.msg
    else:
        reason = str(exc)
        if isinstance(exc, ConnectionRefusedError) or 'Connection refused' in reason or 'refused' in reason.lower():
            p = urlparse(url)
            host = p.hostname or ''
            port = p.port or (443 if p.scheme == 'https' else 80)
            reason = f"dial tcp {host}:{port}: connect: connection refused"
        elif isinstance(exc, TimeoutError) or 'timed out' in reason.lower():
            reason = 'Client.Timeout exceeded while awaiting headers'
        elif 'Name or service not known' in reason or 'Temporary failure in name resolution' in reason or 'nodename nor servname' in reason:
            host = urlparse(url).hostname or ''
            reason = f"dial tcp: lookup {host}: no such host"
    return f"can't get the url {mtitle} \"{disp}\": {reason}"

def single_http_request(method, url_arg, flags, header_pairs, data_pairs, want_body=True, redirects=0):
    url = ensure_url(url_arg)
    if method in ('GET', 'HEAD') and data_pairs:
        url = append_get_query(url, data_pairs)
    p = urlparse(url)
    if p.scheme not in ('http', 'https'):
        raise HTTPErrorForLog(f"unsupported protocol scheme \"{p.scheme}\"")
    if not p.hostname:
        raise HTTPErrorForLog('http: no Host in request URL')
    body, headers = prepare_body_and_headers(method, flags, header_pairs, data_pairs)
    for k in list(headers.keys()):
        if k == '':
            raise HTTPErrorForLog('net/http: invalid header field name ""')
    target = urlunparse(('', '', p.path or '/', p.params, p.query, p.fragment))
    if target == '': target = '/'
    host = p.hostname
    port = p.port or (443 if p.scheme == 'https' else 80)
    connect_host, connect_port = host, port
    use_ssl = (p.scheme == 'https')
    # Simple HTTP proxy support.
    if flags.get('proxy'):
        proxy_url = ensure_url(flags['proxy'])
        pp = urlparse(proxy_url)
        if pp.hostname:
            connect_host = pp.hostname; connect_port = pp.port or 80
            if p.scheme == 'http':
                target = url
    try:
        if use_ssl and not (flags.get('proxy') and p.scheme == 'http'):
            context = ssl._create_unverified_context() if flags.get('insecure') else ssl.create_default_context()
            conn = http.client.HTTPSConnection(connect_host, connect_port, timeout=30, context=context)
        else:
            conn = http.client.HTTPConnection(connect_host, connect_port, timeout=30)
        conn.putrequest(method, target, skip_host=True, skip_accept_encoding=True)
        host_header = p.netloc
        conn.putheader('Host', host_header)
        for k, v in headers.items():
            conn.putheader(k, v)
        if body is not None:
            conn.putheader('Content-Length', str(len(body)))
        conn.endheaders(body if body is not None else None)
        resp = conn.getresponse()
        data = resp.read() if want_body else b''
        hdrs = resp.getheaders()
        status = resp.status
        # Follow redirects as net/http does for normal client calls.
        if status in (301, 302, 303, 307, 308) and redirects < 10:
            loc = dict((k.lower(), v) for k, v in hdrs).get('location')
            if loc:
                nurl = urljoin(url, loc)
                nmethod = method
                nbodydata = data_pairs
                nflags = dict(flags)
                if status in (301, 302, 303) and method not in ('GET', 'HEAD'):
                    nmethod = 'GET'; nbodydata = []; nflags['body'] = ''
                conn.close()
                return single_http_request(nmethod, nurl, nflags, header_pairs, nbodydata, want_body, redirects+1)
        enc = ''
        for k, v in hdrs:
            if k.lower() == 'content-encoding': enc = v.lower()
        if enc == 'gzip':
            try: data = gzip.decompress(data)
            except Exception: pass
        conn.close()
        return status, hdrs, data, url
    except Exception:
        try:
            conn.close()
        except Exception:
            pass
        raise

def do_request(flags, rest, suppress_output=False):
    method, url_arg, header_pairs, data_pairs = build_request(flags, rest)
    url_for_err = ensure_url(url_arg)
    if method in ('GET', 'HEAD') and data_pairs:
        url_for_err = append_get_query(url_for_err, data_pairs)
    try:
        status, hdrs, data, final_url = single_http_request(method, url_arg, flags, header_pairs, data_pairs, want_body=True)
    except Exception as e:
        log_fatal('bat.go:215', connection_error_message(method, url_for_err, e), 1)
    if not suppress_output:
        render_response(data, hdrs, flags.get('pretty', True))
    return status, len(data), data

def percentile(vals, p):
    if not vals: return 0.0
    vals = sorted(vals)
    idx = int(math.ceil((p/100.0)*len(vals))) - 1
    idx = max(0, min(idx, len(vals)-1))
    return vals[idx]

def run_bench(flags, rest):
    # Build once to validate args.
    method, url_arg, header_pairs, data_pairs = build_request(flags, rest)
    n = max(0, int(flags.get('N', 1000)))
    c = max(1, int(flags.get('C', 100)))
    results = []
    errors = {}
    lock = threading.Lock()
    counter = {'i': 0}
    start_all = time.time()
    def worker():
        while True:
            with lock:
                if counter['i'] >= n: return
                counter['i'] += 1
            st = time.time()
            try:
                status, hdrs, data, final_url = single_http_request(method, url_arg, flags, header_pairs, data_pairs, want_body=True)
                dt = time.time() - st
                with lock:
                    results.append((dt, status, len(data)))
            except Exception as e:
                dt = time.time() - st
                err = connection_error_message(method, ensure_url(url_arg), e).split(': ', 1)[-1]
                with lock:
                    errors[err] = errors.get(err, 0) + 1
    threads = [threading.Thread(target=worker) for _ in range(min(c, max(n,1)))]
    for t in threads: t.daemon = True; t.start()
    for t in threads: t.join()
    total = max(time.time() - start_all, 0.000001)
    if results:
        lats = [r[0] for r in results]
        total_data = sum(r[2] for r in results)
        avg = sum(lats)/len(lats)
        sys.stdout.write("\nSummary:\n")
        sys.stdout.write(f"  Total:\t{total:.4f} secs.\n")
        sys.stdout.write(f"  Slowest:\t{max(lats):.4f} secs.\n")
        sys.stdout.write(f"  Fastest:\t{min(lats):.4f} secs.\n")
        sys.stdout.write(f"  Average:\t{avg:.4f} secs.\n")
        sys.stdout.write(f"  Requests/sec:\t{(len(results)/total):.4f}\n")
        sys.stdout.write(f"  Total Data Received:\t{total_data} bytes.\n")
        per = int(total_data/len(results)) if results else 0
        sys.stdout.write(f"  Response Size per Request:\t{per} bytes.\n\n")
        counts = {}
        for _, st, _ in results: counts[st] = counts.get(st, 0)+1
        sys.stdout.write("Status code distribution:\n")
        for st in sorted(counts): sys.stdout.write(f"  [{st}]\t{counts[st]} responses\n")
        sys.stdout.write("\nResponse time histogram:\n")
        mn, mx = min(lats), max(lats)
        width = (mx-mn)/10.0 if mx > mn else 0.0
        maxbucket = 1
        buckets=[]
        for i in range(11):
            lo = mn + width*i
            if width == 0:
                cnt = len(lats) if i == 0 else 0
            elif i == 10:
                cnt = sum(1 for v in lats if v >= lo)
            else:
                hi = mn + width*(i+1)
                cnt = sum(1 for v in lats if lo <= v < hi)
            buckets.append((lo,cnt)); maxbucket=max(maxbucket,cnt)
        for lo,cnt in buckets:
            bar = '∎' * int(40*cnt/maxbucket) if cnt else ''
            sys.stdout.write(f"  {lo:.3f} [{cnt}]\t|{bar}\n")
        sys.stdout.write("\nLatency distribution:\n")
        for p in (10,25,50,75,90,95,99):
            if len(lats) >= 2 or p in (10,25):
                sys.stdout.write(f"  {p}% in {percentile(lats,p):.4f} secs.\n")
    if errors:
        sys.stdout.write("\nError distribution:\n")
        for msg, cnt in errors.items():
            sys.stdout.write(f"  [{cnt}]\t{msg}\n")
    sys.stdout.flush()
    return 0

def main(argv):
    try:
        flags, rest = parse_flags(argv)
    except FlagError as e:
        sys.stderr.write(str(e) + "\n")
        print_usage()
        return 2
    if flags.get('version'):
        sys.stdout.write(f"Version: {VERSION}\n")
        return 0
    if flags.get('bench'):
        return run_bench(flags, rest)
    do_request(flags, rest, suppress_output=False)
    return 0

if __name__ == '__main__':
    try:
        raise SystemExit(main(sys.argv[1:]))
    except BrokenPipeError:
        raise SystemExit(1)
